insert into phrases (id, locale, category, source_text, literal, natural_text, cultural_note, pronunciation, sort_order)
values
  ('greetings-hello', 'es-419', 'greetings', 'Hello', 'Hola', 'Hola', '', 'OH-lah', 0),
  ('greetings-good-morning', 'es-419', 'greetings', 'Good morning', 'Buenos días', 'Buenos días', 'Used until about midday, then buenas tardes. Greeting someone before you ask them anything is expected, not optional — skipping it reads as brusque.', 'BWEH-nohs DEE-ahs', 1),
  ('greetings-thank-you', 'es-419', 'greetings', 'Thank you very much', 'Muchas gracias', 'Muchas gracias', 'GRAH-see-ahs, never grah-THEE-ahs. The Castilian lisp is not used anywhere in Latin America.', 'MOO-chahs GRAH-see-ahs', 2),
  ('greetings-excuse-me', 'es-419', 'greetings', 'Excuse me', 'Disculpe', 'Disculpe', 'For getting a stranger''s attention. Permiso is for squeezing past someone, and perdón is for apologising after you have already bumped into them.', 'dees-KOOL-peh', 3),
  ('greetings-do-you-speak-english', 'es-419', 'greetings', 'Do you speak English?', '¿Habla usted inglés?', '¿Habla inglés?', '', 'AH-blah een-GLEHS', 4),
  ('greetings-little-spanish', 'es-419', 'greetings', 'I don''t speak much Spanish', 'No hablo mucho español', 'Hablo poquito español', 'Saying this early nearly always makes the other person slow down. Poquito is warmer than the flat no hablo and tends to get a friendlier response.', 'AH-bloh poh-KEE-toh ehs-pah-NYOL', 5),
  ('greetings-nice-to-meet-you', 'es-419', 'greetings', 'Nice to meet you', 'Es un placer conocerlo', 'Mucho gusto', '', 'MOO-choh GOOS-toh', 6),
  ('dining-menu', 'es-419', 'dining', 'Could I see the menu?', '¿Podría ver el menú?', '¿Me da el menú, por favor?', 'La carta is the more common word in many countries' || chr(59) || ' both are understood everywhere.', 'meh dah ehl meh-NOO, por fah-VOR', 7),
  ('dining-table-for-two', 'es-419', 'dining', 'A table for two, please', 'Una mesa para dos, por favor', 'Una mesa para dos, por favor', '', 'OO-nah MEH-sah PAH-rah dohs, por fah-VOR', 8),
  ('dining-vegetarian', 'es-419', 'dining', 'I''m vegetarian', 'Soy vegetariano', 'Soy vegetariano', 'Say vegetariana if you are a woman. Worth adding no como pollo ni pescado — chicken and fish are often not counted as meat.', 'soy veh-heh-tah-ree-AH-noh', 9),
  ('dining-does-this-have-meat', 'es-419', 'dining', 'Does this have meat in it?', '¿Esto contiene carne?', '¿Esto lleva carne?', 'Lleva starts with a soft y sound, not a hard L. Beans and rice are very often cooked with pork fat, so this is worth asking even about a side dish.', 'EHS-toh YEH-vah KAR-neh', 10),
  ('dining-allergy', 'es-419', 'dining', 'I have an allergy to...', 'Tengo una alergia a...', 'Soy alérgico a...', 'Alérgica if you are a woman. The g in alérgico is a throaty h sound.', 'soy ah-LEHR-hee-koh ah', 11),
  ('dining-check', 'es-419', 'dining', 'The check, please', 'La cuenta, por favor', 'La cuenta, por favor', 'It will not be brought until you ask. Sitting on a finished table is normal and nobody is trying to rush you out.', 'lah KWEHN-tah, por fah-VOR', 12),
  ('dining-tip-included', 'es-419', 'dining', 'Is the tip included?', '¿La propina está incluida?', '¿La propina está incluida?', 'Often added automatically as propina or servicio. Check before tipping again — expectations vary a lot from country to country.', 'lah proh-PEE-nah ehs-TAH een-kloo-EE-dah', 13),
  ('transit-where-bus', 'es-419', 'transit', 'Where do I catch the bus?', '¿Dónde tomo el autobús?', '¿Dónde tomo el autobús?', 'The local word changes by country — camión, colectivo, micro, guagua. Autobús is understood everywhere, so it is the safe one to travel with.', 'DOHN-deh TOH-moh ehl ow-toh-BOOS', 14),
  ('transit-fare', 'es-419', 'transit', 'How much is the fare?', '¿Cuánto cuesta el pasaje?', '¿Cuánto es el pasaje?', '', 'KWAN-toh ehs ehl pah-SAH-heh', 15),
  ('transit-this-address', 'es-419', 'transit', 'Please take me to this address', 'Por favor, lléveme a esta dirección', 'Lléveme a esta dirección, por favor', 'Showing the address on your phone while you say it removes most of the risk of being misheard.', 'YEH-veh-meh ah EHS-tah dee-rehk-see-OHN, por fah-VOR', 16),
  ('transit-airport', 'es-419', 'transit', 'Does this go to the airport?', '¿Este va al aeropuerto?', '¿Este va al aeropuerto?', '', 'EHS-teh vah ahl ah-eh-roh-PWEHR-toh', 17),
  ('transit-train-station', 'es-419', 'transit', 'Where is the train station?', '¿Dónde está la estación de tren?', '¿Dónde queda la estación de tren?', 'Queda is the more natural verb for where a fixed place is. Estación is ehs-tah-see-OHN — the c is an s.', 'DOHN-deh KEH-dah lah ehs-tah-see-OHN deh trehn', 18),
  ('transit-meter', 'es-419', 'transit', 'Could you use the meter?', '¿Podría usar el taxímetro?', '¿Me pone el taxímetro, por favor?', 'Settle the meter or agree a flat price before the car moves. Asking once you are already riding leaves you with no room to negotiate.', 'meh POH-neh ehl tahk-SEE-meh-troh, por fah-VOR', 19),
  ('transit-stop-here', 'es-419', 'transit', 'Stop here, please', 'Pare aquí, por favor', 'Aquí está bien, gracias', '', 'ah-KEE ehs-TAH bee-EHN, GRAH-see-ahs', 20),
  ('shopping-how-much', 'es-419', 'shopping', 'How much does this cost?', '¿Cuánto cuesta esto?', '¿Cuánto cuesta?', '', 'KWAN-toh KWEHS-tah', 21),
  ('shopping-cards', 'es-419', 'shopping', 'Do you take cards?', '¿Aceptan tarjetas de crédito?', '¿Aceptan tarjeta?', 'The j in tarjeta is a throaty h. Plenty of markets and small shops are cash only, so ask before you pick things up.', 'ah-SEHP-tahn tar-HEH-tah', 22),
  ('shopping-just-looking', 'es-419', 'shopping', 'I''m just looking, thanks', 'Solo estoy mirando, gracias', 'Solo estoy viendo, gracias', '', 'SOH-loh ehs-TOY vee-EHN-doh, GRAH-see-ahs', 23),
  ('shopping-another-size', 'es-419', 'shopping', 'Do you have this in another size?', '¿Tiene esto en otra talla?', '¿Lo tiene en otra talla?', 'Talla is TAH-yah, with a soft y. Use número instead when you mean shoes.', 'loh tee-EH-neh ehn OH-trah TAH-yah', 24),
  ('shopping-better-price', 'es-419', 'shopping', 'Could you give me a better price?', '¿Podría darme un mejor precio?', '¿Me hace un mejor precio?', 'Fine in a market or with a street vendor. In a shop with printed price tags it will just be awkward.', 'meh AH-seh oon meh-HOR PREH-see-oh', 25),
  ('shopping-ill-take-it', 'es-419', 'shopping', 'I''ll take it', 'Lo voy a comprar', 'Me lo llevo', '', 'meh loh YEH-voh', 26),
  ('shopping-change', 'es-419', 'shopping', 'Do you have change?', '¿Tiene cambio?', '¿Tiene cambio?', 'Small vendors frequently cannot break a large note. Breaking big bills at a supermarket early in the day saves a lot of friction later.', 'tee-EH-neh KAHM-bee-oh', 27),
  ('lodging-reservation', 'es-419', 'lodging', 'I have a reservation', 'Tengo una reservación', 'Tengo una reservación', 'Reserva is used just as widely' || chr(59) || ' both are understood.', 'TEHN-goh OO-nah reh-sehr-vah-see-OHN', 28),
  ('lodging-checkout-time', 'es-419', 'lodging', 'What time is check-out?', '¿A qué hora es la salida?', '¿A qué hora es la salida?', 'The h in hora is completely silent.', 'ah keh OH-rah ehs lah sah-LEE-dah', 29),
